import React, { useState, useEffect } from 'react';
import { 
  auth, 
  db,
  createUserWithEmailAndPassword, 
  signInWithEmailAndPassword,
  sendEmailVerification,
  sendPasswordResetEmail,
  updateProfile,
  onAuthStateChanged,
  doc,
  setDoc
} from './firebase.js';
import './App.css';

function App() {
  // ===== Auth State =====
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [showSignup, setShowSignup] = useState(false);
  const [showReset, setShowReset] = useState(false);
  const [showMainApp, setShowMainApp] = useState(false);

  // ===== Login Form State =====
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPassword, setLoginPassword] = useState('');

  // ===== Signup Form State =====
  const [signupUsername, setSignupUsername] = useState('');
  const [signupEmail, setSignupEmail] = useState('');
  const [signupCountry, setSignupCountry] = useState('');
  const [signupCity, setSignupCity] = useState('');
  const [signupPassword, setSignupPassword] = useState('');
  const [signupConfirmPassword, setSignupConfirmPassword] = useState('');

  // ===== Reset Password State =====
  const [resetEmail, setResetEmail] = useState('');

  // ===== PWA Installation Check =====
  const [showLanding, setShowLanding] = useState(true);
  const [activePlatform, setActivePlatform] = useState('android');

  // ===== Check Auth State =====
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
      if (currentUser) {
        if (currentUser.emailVerified) {
          setUser(currentUser);
          setShowMainApp(true);
        } else {
          setUser(currentUser);
          setShowMainApp(false);
          alert('📧 Please verify your email before logging in. Check your inbox!');
        }
      } else {
        setUser(null);
        setShowMainApp(false);
      }
      setLoading(false);
    });
    return unsubscribe;
  }, []);

  // ===== Check PWA Installation =====
  useEffect(() => {
    const isInStandaloneMode = window.matchMedia('(display-mode: standalone)').matches;
    const isIOSStandalone = window.navigator.standalone === true;
    
    if (isInStandaloneMode || isIOSStandalone) {
      setShowLanding(false);
    }

    const userAgent = navigator.userAgent.toLowerCase();
    if (userAgent.includes('iphone') || userAgent.includes('ipad') || userAgent.includes('mac')) {
      setActivePlatform('ios');
    } else if (userAgent.includes('android')) {
      setActivePlatform('android');
    }
  }, []);

  // ===== LOGIN =====
  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const userCredential = await signInWithEmailAndPassword(auth, loginEmail, loginPassword);
      const user = userCredential.user;
      
      if (!user.emailVerified) {
        alert('📧 Please verify your email first. Check your inbox!');
        await auth.signOut();
        return;
      }
      
      setUser(user);
      setShowMainApp(true);
      alert('✅ Welcome back!');
    } catch (error) {
      alert('❌ ' + error.message);
    }
  };

  // ===== SIGNUP =====
  const handleSignup = async (e) => {
    e.preventDefault();

    if (signupPassword !== signupConfirmPassword) {
      alert('❌ Passwords do not match!');
      return;
    }

    if (signupPassword.length < 6) {
      alert('❌ Password must be at least 6 characters!');
      return;
    }

    try {
      const userCredential = await createUserWithEmailAndPassword(auth, signupEmail, signupPassword);
      const user = userCredential.user;

      await updateProfile(user, {
        displayName: signupUsername
      });

      await setDoc(doc(db, 'users', user.uid), {
        username: signupUsername,
        email: signupEmail,
        country: signupCountry,
        city: signupCity,
        createdAt: new Date(),
        uid: user.uid
      });

      await sendEmailVerification(user);
      alert('📧 Verification email sent! Please check your inbox and verify your email before logging in.');

      await auth.signOut();
      setShowSignup(false);
      setLoginEmail(signupEmail);
      
    } catch (error) {
      alert('❌ ' + error.message);
    }
  };

  // ===== RESET PASSWORD =====
  const handleResetPassword = async (e) => {
    e.preventDefault();
    try {
      await sendPasswordResetEmail(auth, resetEmail);
      alert('📧 Password reset email sent! Check your inbox.');
      setShowReset(false);
      setResetEmail('');
    } catch (error) {
      alert('❌ ' + error.message);
    }
  };

  // ===== LOGOUT =====
  const handleLogout = async () => {
    await auth.signOut();
    setUser(null);
    setShowMainApp(false);
    alert('👋 You have been logged out.');
  };

  // ===== COUNTRIES LIST =====
  const countries = [
    'Afghanistan', 'Albania', 'Algeria', 'Andorra', 'Angola', 'Antigua and Barbuda', 'Argentina', 'Armenia', 'Australia', 'Austria', 'Azerbaijan',
    'Bahamas', 'Bahrain', 'Bangladesh', 'Barbados', 'Belarus', 'Belgium', 'Belize', 'Benin', 'Bhutan', 'Bolivia', 'Bosnia and Herzegovina', 'Botswana', 'Brazil', 'Brunei', 'Bulgaria', 'Burkina Faso', 'Burundi',
    'Cambodia', 'Cameroon', 'Canada', 'Cape Verde', 'Central African Republic', 'Chad', 'Chile', 'China', 'Colombia', 'Comoros', 'Congo', 'Costa Rica', 'Croatia', 'Cuba', 'Cyprus', 'Czech Republic',
    'Denmark', 'Djibouti', 'Dominica', 'Dominican Republic',
    'Ecuador', 'Egypt', 'El Salvador', 'Equatorial Guinea', 'Eritrea', 'Estonia', 'Eswatini', 'Ethiopia',
    'Fiji', 'Finland', 'France',
    'Gabon', 'Gambia', 'Georgia', 'Germany', 'Ghana', 'Greece', 'Grenada', 'Guatemala', 'Guinea', 'Guinea-Bissau', 'Guyana',
    'Haiti', 'Honduras', 'Hungary',
    'Iceland', 'India', 'Indonesia', 'Iran', 'Iraq', 'Ireland', 'Israel', 'Italy',
    'Jamaica', 'Japan', 'Jordan',
    'Kazakhstan', 'Kenya', 'Kiribati', 'Korea, North', 'Korea, South', 'Kuwait', 'Kyrgyzstan',
    'Laos', 'Latvia', 'Lebanon', 'Lesotho', 'Liberia', 'Libya', 'Liechtenstein', 'Lithuania', 'Luxembourg',
    'Madagascar', 'Malawi', 'Malaysia', 'Maldives', 'Mali', 'Malta', 'Marshall Islands', 'Mauritania', 'Mauritius', 'Mexico', 'Micronesia', 'Moldova', 'Monaco', 'Mongolia', 'Montenegro', 'Morocco', 'Mozambique', 'Myanmar',
    'Namibia', 'Nauru', 'Nepal', 'Netherlands', 'New Zealand', 'Nicaragua', 'Niger', 'Nigeria', 'North Macedonia', 'Norway',
    'Oman',
    'Pakistan', 'Palau', 'Panama', 'Papua New Guinea', 'Paraguay', 'Peru', 'Philippines', 'Poland', 'Portugal',
    'Qatar',
    'Romania', 'Russia', 'Rwanda',
    'Saint Kitts and Nevis', 'Saint Lucia', 'Saint Vincent and the Grenadines', 'Samoa', 'San Marino', 'Sao Tome and Principe', 'Saudi Arabia', 'Senegal', 'Serbia', 'Seychelles', 'Sierra Leone', 'Singapore', 'Slovakia', 'Slovenia', 'Solomon Islands', 'Somalia', 'South Africa', 'Spain', 'Sri Lanka', 'Sudan', 'Suriname', 'Sweden', 'Switzerland', 'Syria',
    'Taiwan', 'Tajikistan', 'Tanzania', 'Thailand', 'Timor-Leste', 'Togo', 'Tonga', 'Trinidad and Tobago', 'Tunisia', 'Turkey', 'Turkmenistan', 'Tuvalu',
    'Uganda', 'Ukraine', 'United Arab Emirates', 'United Kingdom', 'United States', 'Uruguay', 'Uzbekistan',
    'Vanuatu', 'Vatican City', 'Venezuela', 'Vietnam',
    'Yemen',
    'Zambia', 'Zimbabwe'
  ];

  // ===== LANDING PAGE =====
  const LandingPage = () => {
    const [platform, setPlatform] = useState(activePlatform);

    return (
      <div className="Landing">
        <div className="Landing-header">
          <div className="Landing-hero">
            <span className="Landing-emoji">🏠</span>
            <h1>The House</h1>
            <p className="Landing-tagline">Reality TV Companion App</p>
          </div>
          <div className="Landing-content">
            <h2>📲 Install The House</h2>
            <p className="Landing-sub">Get the full experience by installing our app</p>
            <div className="Platform-tabs">
              <button className={`Tab-button ${platform === 'android' ? 'active' : ''}`} onClick={() => setPlatform('android')}>🤖 Android</button>
              <button className={`Tab-button ${platform === 'ios' ? 'active' : ''}`} onClick={() => setPlatform('ios')}>🍎 iOS</button>
            </div>
            <div className="Install-instructions">
              {platform === 'android' && (
                <div className="Instruction-card">
                  <div className="Platform-icon">🤖</div>
                  <h3>Android (Chrome)</h3>
                  <ol>
                    <li>Tap the <strong>⋮</strong> menu (3 dots)</li>
                    <li>Select <strong>"Add to Home screen"</strong></li>
                    <li>Tap <strong>"Install"</strong></li>
                    <li>Launch from your home screen</li>
                  </ol>
                </div>
              )}
              {platform === 'ios' && (
                <div className="Instruction-card">
                  <div className="Platform-icon">🍎</div>
                  <h3>iPhone / iPad (Safari)</h3>
                  <ol>
                    <li>Tap the <strong>Share</strong> button <span className="Icon">⎔</span></li>
                    <li>Scroll down and tap <strong>"Add to Home Screen"</strong></li>
                    <li>Tap <strong>"Add"</strong> in the top right</li>
                    <li>Launch from your home screen</li>
                  </ol>
                </div>
              )}
            </div>
            <button className="Continue-button" onClick={() => {
              if (window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone) {
                setShowLanding(false);
              } else {
                alert('📱 After installing, reopen the app from your home screen!');
              }
            }}>✅ I've installed it!</button>
            <p className="Landing-footer">⚡ No app store needed • Works offline • Free</p>
          </div>
        </div>
      </div>
    );
  };

  // ===== LOGIN PAGE =====
  const LoginPage = () => (
    <div className="Auth-container">
      <div className="Auth-card">
        <div className="Auth-logo">🏠</div>
        <h1>The House</h1>
        <p className="Auth-subtitle">Welcome back!</p>
        <form onSubmit={handleLogin}>
          <input type="email" placeholder="Email" value={loginEmail} onChange={(e) => setLoginEmail(e.target.value)} required />
          <input type="password" placeholder="Password" value={loginPassword} onChange={(e) => setLoginPassword(e.target.value)} required />
          <button type="submit" className="Auth-button">Login</button>
        </form>
        <div className="Auth-links">
          <button onClick={() => { setShowSignup(true); setShowReset(false); }}>Don't have an account? Sign Up</button>
          <button onClick={() => { setShowReset(true); setShowSignup(false); }}>Forgot Password?</button>
        </div>
      </div>
    </div>
  );

  // ===== SIGNUP PAGE =====
  const SignupPage = () => (
    <div className="Auth-container">
      <div className="Auth-card">
        <div className="Auth-logo">🏠</div>
        <h1>The House</h1>
        <p className="Auth-subtitle">Create your account</p>
        <form onSubmit={handleSignup}>
          <input type="text" placeholder="Username" value={signupUsername} onChange={(e) => setSignupUsername(e.target.value)} required />
          <input type="email" placeholder="Email" value={signupEmail} onChange={(e) => setSignupEmail(e.target.value)} required />
          <select value={signupCountry} onChange={(e) => setSignupCountry(e.target.value)} required>
            <option value="">Select Country</option>
            {countries.map((c) => <option key={c}>{c}</option>)}
          </select>
          <input type="text" placeholder="City" value={signupCity} onChange={(e) => setSignupCity(e.target.value)} required />
          <input type="password" placeholder="Password (min 6 chars)" value={signupPassword} onChange={(e) => setSignupPassword(e.target.value)} required minLength="6" />
          <input type="password" placeholder="Confirm Password" value={signupConfirmPassword} onChange={(e) => setSignupConfirmPassword(e.target.value)} required />
          <button type="submit" className="Auth-button">Sign Up</button>
        </form>
        <div className="Auth-links">
          <button onClick={() => { setShowSignup(false); }}>Already have an account? Login</button>
        </div>
      </div>
    </div>
  );

  // ===== RESET PASSWORD PAGE =====
  const ResetPasswordPage = () => (
    <div className="Auth-container">
      <div className="Auth-card">
        <div className="Auth-logo">🔑</div>
        <h1>Reset Password</h1>
        <p className="Auth-subtitle">We'll send you a reset link</p>
        <form onSubmit={handleResetPassword}>
          <input type="email" placeholder="Email" value={resetEmail} onChange={(e) => setResetEmail(e.target.value)} required />
          <button type="submit" className="Auth-button">Send Reset Link</button>
        </form>
        <div className="Auth-links">
          <button onClick={() => { setShowReset(false); }}>Back to Login</button>
        </div>
      </div>
    </div>
  );

  // ===== MAIN APP (Protected) =====
  const MainApp = () => {
    const [votes, setVotes] = useState(0);
    
    return (
      <div className="App">
        <header className="App-header">
          <span style={{ fontSize: '4rem' }}>🏠</span>
          <h1>The House</h1>
          <p>Welcome, {user?.displayName || user?.email}!</p>
          <button onClick={() => setVotes(votes + 1)}>❤️ Vote: {votes}</button>
          <button onClick={handleLogout} style={{ marginTop: '1rem', background: '#555' }}>🚪 Logout</button>
          <p style={{ fontSize: '0.7rem', color: '#555', marginTop: '2rem' }}>📱 Protected Main App</p>
        </header>
      </div>
    );
  };

  // ===== LOADING =====
  if (loading) {
    return (
      <div className="Auth-container">
        <div className="Auth-card">
          <h1 style={{ textAlign: 'center' }}>🏠</h1>
          <p style={{ textAlign: 'center', color: '#a7a9be' }}>Loading...</p>
        </div>
      </div>
    );
  }

  // ===== RENDER =====
  if (showLanding) {
    return <LandingPage />;
  }

  if (showMainApp && user) {
    return <MainApp />;
  }

  if (showReset) {
    return <ResetPasswordPage />;
  }

  if (showSignup) {
    return <SignupPage />;
  }

  return <LoginPage />;
}

export default App;
